fn len(s: &String) -> usize { s.len() }

let s = String::from("hi");
let l = len(&s);     // borrow — s still owned by caller
println!("{s} {l}"); // OK

fn push(s: &mut String) { s.push('!'); }

let mut s = String::from("hi");
push(&mut s);
println!("{s}");   // "hi!"

